local Cooper = {}
local PRODUCTS = {
    barrel = { name = "Sod", woodCost = 5, ironCost = 1, time = 3, cost = 50, capacity = 200, description = "Sod za shranjevanje." },
    cask = { name = "Bočka", woodCost = 3, ironCost = 1, time = 2, cost = 30, capacity = 100, description = "Manjša bočka." },
    tun = { name = "Tuna", woodCost = 15, ironCost = 3, time = 7, cost = 200, capacity = 1000, description = "Velika tuna za vino." },
    firkin = { name = "Firkin", woodCost = 2, time = 1, cost = 15, capacity = 50, description = "Majhna sodčka." },
    hogshead = { name = "Hogshead", woodCost = 10, ironCost = 2, time = 5, cost = 120, capacity = 500, description = "Srednja sod za pivo." },
    butt = { name = "Butt", woodCost = 12, ironCost = 2, time = 6, cost = 150, capacity = 700, description = "Veliki sod za sherry." },
}
local BUILDINGS = {
    workshop = { name = "Sodarska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    cooperage = { name = "Sodarna", cost = { gold = 800, wood = 300, iron = 50 }, upkeep = 20, qualityBonus = 15 },
    drying_yard = { name = "Sušilno dvorišče", cost = { gold = 400, wood = 200 }, upkeep = 8, qualityBonus = 10 },
    royal_cooperage = { name = "Kraljevska sodarna", cost = { gold = 3000, wood = 500, stone = 500, iron = 100 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 10 },
}
Cooper.woodStock = 20; Cooper.ironStock = 10; Cooper.productStock = {}; Cooper.buildings = {}; Cooper.cooper = nil
Cooper.activeMaking = {}; Cooper.totalProducts = 0; Cooper.dayTimer = 0
function Cooper.init() Cooper.woodStock=20; Cooper.ironStock=10; Cooper.productStock={}; Cooper.buildings={}; Cooper.cooper=nil; Cooper.activeMaking={}; Cooper.totalProducts=0; Cooper.dayTimer=0; print("[Cooper] Royal Cooper & Barrel Maker System initialized (6 products, 4 buildings)") end
function Cooper.hireCooper(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Cooper.cooper={name=n or ("Sodar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sodar najet: %s (spretnost: %d)",Cooper.cooper.name,s),"success") end; return true end
function Cooper.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Cooper.build(id) local ok,e=Cooper.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Cooper.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Cooper.getQualityBonus() local b=0; for _,bd in ipairs(Cooper.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Cooper.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if Cooper.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and Cooper.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if #Cooper.buildings==0 then return false,"Potrebna sodarna" end; if not Cooper.cooper then return false,"Potreben sodar" end; return true end
function Cooper.make(pt) local ok,e=Cooper.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; Cooper.woodStock=Cooper.woodStock-(d.woodCost or 0); if d.ironCost then Cooper.ironStock=Cooper.ironStock-d.ironCost end; local t=d.time; if Cooper.cooper then t=math.max(1,t-math.floor(Cooper.cooper.skill/15)) end; table.insert(Cooper.activeMaking,{id="barrel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,capacity=d.capacity,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function Cooper.completeMaking(m) local q=1.0+(Cooper.getQualityBonus()/100); if Cooper.cooper then q=q+(Cooper.cooper.skill/200) end; q=math.min(2.0,q); Cooper.productStock[m.productType]=(Cooper.productStock[m.productType] or 0)+1; Cooper.totalProducts=Cooper.totalProducts+1; if Cooper.cooper then Cooper.cooper.itemsMade=Cooper.cooper.itemsMade+1; if math.random()<0.15 then Cooper.cooper.skill=math.min(100,Cooper.cooper.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sod izdelan: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Cooper.update(dt) if not _G.state then return end; Cooper.dayTimer=Cooper.dayTimer+dt; if Cooper.dayTimer>=30 then Cooper.dayTimer=0; for i=#Cooper.activeMaking,1,-1 do local m=Cooper.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Cooper.completeMaking(m); table.remove(Cooper.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Cooper.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Cooper.cooper then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Cooper.getStats() return {woodStock=Cooper.woodStock,ironStock=Cooper.ironStock,productStock=Cooper.productStock,numBuildings=#Cooper.buildings,hasCooper=Cooper.cooper~=nil,cooperName=Cooper.cooper and Cooper.cooper.name or "—",cooperSkill=Cooper.cooper and Cooper.cooper.skill or 0,activeMaking=#Cooper.activeMaking,totalProducts=Cooper.totalProducts} end
return Cooper
